42	import org.springframework.samples.petclinic.rest.advice.DailyRegistrationLimitException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateEmailException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
45	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
47	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
