49	import org.springframework.samples.petclinic.rest.api.OwnersApi;
50	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
51	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
52	import org.springframework.samples.petclinic.rest.dto.PetDto;
53	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
54	import org.springframework.samples.petclinic.rest.dto.VisitDto;
55	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
76	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
77	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
81	
82	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper) {
97	        this.clinicService = clinicService;
98	        this.ownerMapper = ownerMapper;
99	        this.petMapper = petMapper;
100	        this.visitMapper = visitMapper;
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
106	        Collection<Owner> owners;
107	        if (lastName != null) {
108	            owners = this.clinicService.findOwnerByLastName(lastName);
109	        } else {
110	            owners = this.clinicService.findAllOwners();
111	        }
112	        if (owners.isEmpty()) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
121	        Owner owner = this.clinicService.findOwnerById(ownerId);
122	        if (owner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
131	        List<String> missingFields = new ArrayList<>();
132	        if (isBlank(ownerFieldsDto.getFirstName())) {
133	            missingFields.add("firstName");
134	        }
135	        if (isBlank(ownerFieldsDto.getLastName())) {
136	            missingFields.add("lastName");
137	        }
138	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
139	        if (isBlank(normalizedAddress)) {
140	            missingFields.add("address");
141	        }
142	        if (isBlank(ownerFieldsDto.getCity())) {
143	            missingFields.add("city");
144	        }
145	        if (isBlank(ownerFieldsDto.getTelephone())) {
146	            missingFields.add("telephone");
147	        }
148	        if (!missingFields.isEmpty()) {
149	            throw new MissingOwnerFieldsException(missingFields);
150	        }
151	        LocalDate registrationDate = toBusinessDay(
152	            ownerFieldsDto.getRegistrationDate() != null
153	                ? ownerFieldsDto.getRegistrationDate()
154	                : LocalDate.now());
155	        long registeredOnDay = this.clinicService.findAllOwners().stream()
156	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
157	            .count();
158	        if (registeredOnDay >= 100) {
159	            throw new DailyRegistrationLimitException(
160	                "100 or more owners have already been registered today");
161	        }
162	        boolean bulkSignupWarning = registeredOnDay > 80;
163	        String city = ownerFieldsDto.getCity();
164	        long ownersInCity = this.clinicService.findAllOwners().stream()
165	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
166	            .count();
167	        if (ownersInCity >= 50) {
168	            throw new CityAtCapacityException(
169	                "the owner's city already contains 50 or more owners");
170	        }
171	        ownerFieldsDto.setAddress(normalizedAddress);
172	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
173	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
174	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
175	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
176	            .toList();
177	        String householdId = null;
178	        if (!householdMembers.isEmpty()) {
179	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
180	                throw new DuplicateHouseholdException(
181	                    "an owner with the same last name and address already exists");
182	            }
183	            // Joining an existing household: share a stable identifier with every member,
184	            // backfilling any members created before the household was formed.
185	            householdId = householdId(lastName, normalizedAddress);
186	            for (Owner member : householdMembers) {
187	                if (!householdId.equals(member.getHouseholdId())) {
188	                    member.setHouseholdId(householdId);
189	                    this.clinicService.saveOwner(member);
190	                }
191	            }
192	        }
193	        String telephone = toE164(ownerFieldsDto.getTelephone());
194	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
195	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
196	        if (telephoneInUse) {
197	            throw new DuplicateTelephoneException(
198	                "an owner with the same E.164 telephone already exists");
199	        }
200	        ownerFieldsDto.setTelephone(telephone);
201	        String email = normalizeEmail(ownerFieldsDto.getEmail());
202	        if (email != null) {
203	            boolean emailInUse = this.clinicService.findAllOwners().stream()
204	                .anyMatch(existing -> existing.getEmail() != null
205	                    && email.equalsIgnoreCase(existing.getEmail()));
206	            if (emailInUse) {
207	                throw new DuplicateEmailException(
208	                    "an owner with the same lower-cased email already exists");
209	            }
210	        }
211	        ownerFieldsDto.setEmail(email);
212	        HttpHeaders headers = new HttpHeaders();
213	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
214	        owner.setRegistrationDate(registrationDate);
215	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
216	        owner.setHouseholdId(householdId);
217	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
218	        owner.setBulkSignupWarning(bulkSignupWarning);
219	        // Household size after this create: existing members plus the owner being created.
220	        owner.setHouseholdSize(householdMembers.size() + 1);
221	        this.clinicService.saveOwner(owner);
222	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
223	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
224	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
225	            ownerDto.getMembershipLevel());
226	        headers.setLocation(UriComponentsBuilder.newInstance()
227	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
228	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner == null) {
236	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	        }
238	        currentOwner.setAddress(ownerFieldsDto.getAddress());
239	        currentOwner.setCity(ownerFieldsDto.getCity());
240	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
241	        currentOwner.setLastName(ownerFieldsDto.getLastName());
242	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
243	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
244	        this.clinicService.saveOwner(currentOwner);
245	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
249	    @Transactional
250	    @Override
251	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        this.clinicService.deleteOwner(owner);
257	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
263	        Owner owner = this.clinicService.findOwnerById(ownerId);
264	        if (owner == null) {
265	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	        }
267	        HttpHeaders headers = new HttpHeaders();
268	        Pet pet = petMapper.toPet(petFieldsDto);
269	        owner.setId(ownerId);
270	        pet.setOwner(owner);
271	        pet.getType().setName(null);
272	        this.clinicService.savePet(pet);
273	        PetDto petDto = petMapper.toPetDto(pet);
274	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
275	            .buildAndExpand(pet.getId()).toUri());
276	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
277	    }
278	
279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
282	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
283	        if (currentOwner != null) {
284	            Pet currentPet = this.clinicService.findPetById(petId);
285	            if (currentPet != null) {
286	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
287	                currentPet.setName(petFieldsDto.getName());
288	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
289	                this.clinicService.savePet(currentPet);
290	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
291	            }
292	        }
293	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
299	        HttpHeaders headers = new HttpHeaders();
300	        Visit visit = visitMapper.toVisit(visitFieldsDto);
301	        Pet pet = new Pet();
302	        pet.setId(petId);
303	        visit.setPet(pet);
304	        this.clinicService.saveVisit(visit);
305	        VisitDto visitDto = visitMapper.toVisitDto(visit);
306	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
307	            .buildAndExpand(visit.getId()).toUri());
308	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
309	    }
